  "summary": [
    "Anchor on the IOM Missing Migrants Project central Mediterranean fatalities; historical toll ~2,000–2,500 per year (e.g., 2024 ~2,452).",
    "Early-2026 counts (~606 deaths by February) imply a high pace into March, requiring roughly 290 more deaths to hit 900.",
    "Upward drivers: high year-to-date toll, weather-related risk spikes, and ongoing SAR/capsize incidents; downward driver: potential policy/SAR improvements may dampen fatalities.",
    "Bayesian posterior ~71% suggests a plausible but not certain path to 900 by end-March; calibrated range reflects remaining uncertainty."
  ],
  "confidence": "medium",
  "narrative": "Starting from the central Mediterranean reference class, current counts indicate a high but uncertain risk path to 900 deaths by end of March 2026. The 71% posterior reflects substantial but not guaranteed probability, with weather, SAR capacity, and policy actions as key uncertainties shaping the outcome.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class: Central Mediterranean fatalities per year as tracked by IOM Missing Migrants; historically ~2,000–2,500/year (e.g., 2024 ~2,452). Early 2026 counts around 606 by February provide a windowed anchor; anchor probability 0.35 reflects a conservative starting point before updates."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 mortality already high (≈606 deaths by Feb)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A high year-to-date toll signals an elevated risk trajectory into March, making 900 by end of March more plausible than a lower baseline."
      },
      {
        "factor": "Central Mediterranean weather risk spikes (seasonal storms)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather events can sharply increase fatalities and drive monthly totals upward."
      },
      {
        "factor": "Ongoing search-and-rescue constraints and repeated capsizing incidents",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Continued SAR limitations and incidents raise danger with uncertain magnitude."
      },
      {
        "factor": "Policy/SAR capacity improvements or humanitarian interventions",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improved SAR capacity or policy actions could reduce crossings and save lives, dampening the toll."
      },
      {
        "factor": "Data gaps and undercount risk",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Reporting lags and undercount risk could hide additional deaths, adding uncertainty to the estimate."
      }
    ],
    "synthesis_rationale": "Primary drivers are the high early-year toll and expected March weather risks, with policy/SAR improvements acting as a meaningful counterbalance. Given potential correlation among factors (weather, crossings, and SAR responses), a Bayesian-style calibration yields a posterior near 0.71; the range 0.60–0.82 captures remaining uncertainty."
  }
}

